head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > useLocale]<br/>Textarea 컴포넌트에서 클라이언트 다국어를 사용할지 설정합니다.",
    "validation" : [
        "true 설정 시 클라이언트 다국어 키를 이용하여 다국어를 지원하여야 합니다.",
        "true 설정 시 placeholderLocaleRef 속성 또는 tooltipLocaleRef 속성에 설정된 키로 다국어 텍스트를 조회하여야 합니다.",
        "false 설정 시 클라이언트 다국어 키를 이용하지 않아야 합니다.",
        "미설정 시 기본값(false)으로 동작하여 클라이언트 다국어 키를 이용하지 않아야 합니다.",
        "다국어 기능을 사용하려면 config.xml 파일에서 languagePack 항목을 설정하여야 합니다.",
        "다국어 기능은 Key:Value 형식으로 데이터가 정의된 JS 파일에서 Key 값에 해당하는 Value 값을 찾아 특정 속성에 반영하여야 합니다.",
        "클라이언트(웹브라우저)에 설정된 언어에 해당하는 JS 파일이 적용되어야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (textarea 의 다국어 관련 속성: placeholderLocaleRef, tooltipLocaleRef, useLocale)
    let properties = {
        placeholder: "placeholder",
        placeholderLocaleRef: wf_sample.getObj("con_placeholderLocaleRef").getText(),
        useLocale: wf_sample.getObj("con_useLocale").getText(),
        tooltipLocaleRef: wf_sample.getObj("con_tooltipLocaleRef").getText(),
        tooltip: "tooltip",
    };

    let cList = $c.gcm.createCList(properties);

    // textarea 생성 (target1_onclick 에서 placeholder/text/tooltip 정보 출력)
    await $c.gcm.createBasicTextArea(cList, 'ev:onclick="scwin.target1_onclick"');
    target1.setValue("");
}
